package com.primehr.learningdevelopment.participation.api;

import com.primehr.learningdevelopment.participation.api.LdParticipationDtos.*;
import com.primehr.learningdevelopment.participation.application.LdParticipationService;
import com.primehr.security.*;
import jakarta.validation.Valid;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/primehr/v1/learning-development")
public class LdParticipationController {
    private final LdParticipationService service;private final LdParticipationPermissionGuard permission;private final AgencyScopeResolver agency;
    public LdParticipationController(LdParticipationService service,LdParticipationPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}
    private String agency(Authentication a){return agency.resolveAgencyId(a);}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated employee identity is required");return a.getName();}

    @GetMapping("/nominations") public List<NominationResponse> nominations(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){return service.nominations(agency(a),actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token));}
    @GetMapping("/nominations/{id}") public NominationResponse nomination(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){return service.nomination(agency(a),id,actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token));}
    @PostMapping("/nominations") @ResponseStatus(HttpStatus.CREATED) public NominationResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@Valid @RequestBody NominationCreate input){return service.create(agency(a),input,token,actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ADD,token),correlation);}
    @PutMapping("/nominations/{id}") public NominationResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody NominationUpdate input){return service.update(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.EDIT,token),correlation);}
    @PostMapping("/nominations/{id}/{action:submit|recommend|return|approve|cancel}") public NominationResponse transition(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String action,@Valid @RequestBody Transition input){return switch(action){case"submit"->service.submit(agency(a),id,input,token,actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.SUBMIT,token),correlation);case"recommend"->{permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.APPROVE,token);yield service.recommend(agency(a),id,input,token,actor(a),correlation);}case"return"->{permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.APPROVE,token);yield service.returnForChanges(agency(a),id,input,token,actor(a),correlation);}case"approve"->{permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.APPROVE,token);yield service.approve(agency(a),id,input,token,actor(a),correlation);}default->service.cancel(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ARCHIVE,token),correlation);};}

    @GetMapping("/enrollments") public List<EnrollmentResponse> enrollments(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){return service.enrollments(agency(a),actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token));}
    @GetMapping("/enrollments/{id}") public EnrollmentResponse enrollment(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){return service.enrollment(agency(a),id,actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token));}
    @PostMapping("/enrollments/{id}/{action:confirm|decline|cancel}") public EnrollmentResponse enrollmentTransition(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String action,@Valid @RequestBody Transition input){return switch(action){case"confirm"->{permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token);yield service.confirm(agency(a),id,input,token,actor(a),correlation);}case"decline"->{permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token);yield service.decline(agency(a),id,input,actor(a),correlation);}default->service.cancelEnrollment(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.NOMINATION,PrimeHrAction.EDIT,token),correlation);};}
    @PostMapping("/enrollments/{id}/substitution") public EnrollmentResponse substitute(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody SubstitutionInput input){return service.substitute(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.EDIT,token),correlation);}

    @GetMapping("/offerings/{id}/training-order-source") public TrainingOrderResponse trainingOrder(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){var scope=permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.ACCESS,token);return service.trainingOrder(agency(a),id,actor(a),scope);}
    @PostMapping("/offerings/{id}/training-order-source") @ResponseStatus(HttpStatus.CREATED) public TrainingOrderResponse finalizeTrainingOrder(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody TrainingOrderInput input){return service.finalizeTrainingOrder(agency(a),id,input,actor(a),permission.require(LdParticipationPermissionGuard.DELIVERY,PrimeHrAction.FINALIZE,token),correlation);}
}
